"""
Generate a FastMCP server whose tools mirror the operations of a minimal
OpenAPI 3.0 specification, using an httpx.AsyncClient already configured
with the API's base URL.
"""

import asyncio
import httpx
from fastmcp import FastMCP


def build_mcp_server_from_openapi(
    openapi_spec: dict,
    client: httpx.AsyncClient,
    name: str = "OpenAPI MCP Server",
) -> FastMCP:
    """Build a FastMCP server exposing one tool per OpenAPI operation.

    Args:
        openapi_spec: A minimal OpenAPI 3.0 specification as a dict.
        client: An httpx.AsyncClient already configured with the API's
            base URL (and any auth headers needed to call it).
        name: Display name for the generated MCP server.

    Returns:
        A FastMCP server instance ready to run.
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
    )


# --- Example usage -----------------------------------------------------

EXAMPLE_OPENAPI_SPEC = {
    "openapi": "3.0.0",
    "info": {"title": "Petstore-lite API", "version": "1.0.0"},
    "paths": {
        "/pets": {
            "get": {
                "operationId": "listPets",
                "summary": "List all pets",
                "parameters": [
                    {
                        "name": "limit",
                        "in": "query",
                        "required": False,
                        "schema": {"type": "integer"},
                    }
                ],
                "responses": {"200": {"description": "A list of pets"}},
            },
            "post": {
                "operationId": "createPet",
                "summary": "Create a new pet",
                "requestBody": {
                    "required": True,
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {
                                    "name": {"type": "string"},
                                    "tag": {"type": "string"},
                                },
                                "required": ["name"],
                            }
                        }
                    },
                },
                "responses": {"201": {"description": "Pet created"}},
            },
        },
        "/pets/{petId}": {
            "get": {
                "operationId": "getPet",
                "summary": "Get a pet by ID",
                "parameters": [
                    {
                        "name": "petId",
                        "in": "path",
                        "required": True,
                        "schema": {"type": "integer"},
                    }
                ],
                "responses": {"200": {"description": "The requested pet"}},
            },
            "delete": {
                "operationId": "deletePet",
                "summary": "Delete a pet by ID",
                "parameters": [
                    {
                        "name": "petId",
                        "in": "path",
                        "required": True,
                        "schema": {"type": "integer"},
                    }
                ],
                "responses": {"204": {"description": "Pet deleted"}},
            },
        },
    },
}


def main() -> None:
    base_url = "https://api.example.com"
    client = httpx.AsyncClient(base_url=base_url)

    mcp_server = build_mcp_server_from_openapi(
        openapi_spec=EXAMPLE_OPENAPI_SPEC,
        client=client,
        name="Petstore-lite MCP Server",
    )

    async def _list_tools() -> None:
        tools = await mcp_server.get_tools()
        for tool_name in tools:
            print(tool_name)

    asyncio.run(_list_tools())

    mcp_server.run()


if __name__ == "__main__":
    main()

